\begin{tikzpicture}[x=0.035cm,y=1.8cm,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{sineOne}{HTML}{268CFF}
\definecolor{sineTwo}{HTML}{EF6068}
\definecolor{sineThree}{HTML}{4F9B63}
\draw[->,black,line width=0.5pt] (-10,0)--(385,0) node[right] {$\theta$};
\draw[->,black,line width=0.5pt] (0,-1.35)--(0,1.45) node[above] {$y$};
\foreach \a in {30,60,90,120,150,180,210,240,270,300,330,360} {\draw[black,line width=0.4pt] (\a,0.035)--(\a,-0.035);}
\draw[black,line width=0.4pt] (45,0)--(45,0.07);
\foreach \b in {-1,1} {\draw[black,line width=0.4pt] (-3,\b)--(3,\b);\node[left,font=\fontsize{8.5}{10}\selectfont] at (-3,\b) {\special{dvisvgm:raw <g data-graph-text="tick">}$\b$\special{dvisvgm:raw </g>}};}
\node[left=5pt,font=\fontsize{8.5}{10}\selectfont] at (0,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$0^\circ$\special{dvisvgm:raw </g>}};
\draw[sineOne,line width=0.8pt] plot[domain=0:360,samples=241] (\x,{sin(\x)});
\draw[sineTwo,dashed,line width=0.8pt] plot[domain=0:360,samples=361] (\x,{sin(2*\x)});
\draw[sineThree,dash dot,line width=0.8pt] plot[domain=0:360,samples=541] (\x,{sin(3*\x)});
\foreach \a in {30,60,90,120,150,180,210,240,270,300,330,360} {\node[anchor=north east,rotate=60,inner sep=1pt,font=\fontsize{8.5}{10}\selectfont] at (\a,-1.55) {\special{dvisvgm:raw <g data-graph-text="tick">}$\a^\circ$\special{dvisvgm:raw </g>}};}
\node[above,inner sep=1pt,font=\fontsize{8.5}{10}\selectfont] at (45,0.10) {\special{dvisvgm:raw <g data-graph-text="tick">}$45^\circ$\special{dvisvgm:raw </g>}};
\draw[black,fill=white,line width=0.4pt] (0,0) circle[radius=1.5pt];
\draw[black,fill=white,line width=0.4pt] (360,0) circle[radius=1.5pt];
\draw[sineOne,line width=0.8pt] (100,4.4)--(125,4.4);
\node[right] at (140,4.4) {$y=\sin\theta$};
\draw[sineTwo,dashed,line width=0.8pt] (100,3.5)--(125,3.5);
\node[right] at (140,3.5) {$y=\sin 2\theta$};
\draw[sineThree,dash dot,line width=0.8pt] (100,2.6)--(125,2.6);
\node[right] at (140,2.6) {$y=\sin 3\theta$};
\end{tikzpicture}
